def transform(grid):
    def rotate_cw(g):
        return [list(row) for row in zip(*g[::-1])]
    def rotate_ccw(g):
        return [list(row) for row in zip(*g)][::-1]
    def rotate_180(g):
        return [row[::-1] for row in g[::-1]]

    top = [a + b for a, b in zip(grid, rotate_cw(grid))]
    bottom = [a + b for a, b in zip(rotate_ccw(grid), rotate_180(grid))]
    return top + bottom
